script:
(function () {
  'use strict';
  // 457(b) special catch-up worksheet (IRC 457(b)(3); Treas. Reg. 1.457-4(c)(2) and (c)(3)).
  //   Catch-up years: the last three taxable years ending before the year you reach the plan's normal
  //     retirement age (birth year + NRA - 3 to birth year + NRA - 1).
  //   Unused (underutilized) limit: for every earlier year you could take part in the plan, that year's
  //     plan ceiling (the lesser of the 457(e)(15) dollar limit and your includible pay) minus what went
  //     into the plan under it, age 50+ catch-ups left out. Years from 2002 are entered here; earlier
  //     years follow the pre-2002 coordination rules and are entered as a single figure.
  //   Special catch-up ceiling in a catch-up year = lesser of (a) twice the dollar limit or (b) that
  //     year's plan ceiling plus the unused limit still carried in.
  //   Governmental plans: in a catch-up year you get the larger of the special catch-up ceiling or the
  //     basic limit plus the age 50+ catch-up (ages 60-63: the SECURE 2.0 higher amount), never both.
  //   Using the special route uses up unused limit equal to what you defer above the plan ceiling;
  //     years where the age 50+ route is larger leave it untouched. Deferrals can't exceed pay.
  //   Future years use the 2026 dollar amounts (later limits are not yet published).
  // Checked in Node (scratch tests, whole script with a fake DOM):
  //   Treas. Reg. 1.457-4(c)(3)(vi) Example 2: limit $15,000, $2,000 deferred in 2006 -> $13,000 unused;
  //     2007 special ceiling = lesser of $30,000 or $28,000 = $28,000, beats $20,000 (basic + age 50).
  //   1.457-4(c)(2)(iii) Examples 2 and 3: special ceiling $17,000 loses to $20,000; $22,000 wins.
  //   2026, governmental, age 62, $60,000 unused: special = lesser of $49,000 or $84,500 = $49,000 vs
  //     $35,750 (ages 60-63) -> $49,000, leaving $35,500 unused; with $5,000 unused the special
  //     $29,500 loses to $35,750 and the unused amount is kept.
  //   Tax-exempt employer, age 62, $5,000 unused: $29,500 (no age 50+ catch-up).
  //   Pay $40,000 caps every route at $40,000.
  // ---- IRS 457(e)(15) dollar limits by year (IRS COLA tables; 2026: IRS Notice 2025-67) ---------
  var LIMIT_BY_YEAR = { 2002: 11000, 2003: 12000, 2004: 13000, 2005: 14000, 2006: 15000, 2007: 15500, 2008: 15500,
    2009: 16500, 2010: 16500, 2011: 16500, 2012: 17000, 2013: 17500, 2014: 17500, 2015: 18000, 2016: 18000,
    2017: 18000, 2018: 18500, 2019: 19000, 2020: 19500, 2021: 19500, 2022: 20500, 2023: 22500, 2024: 23000,
    2025: 23500, 2026: 24500 };
  var LIMITS = { year: 2026, basic: 24500, catchUp50: 8000, catchUp60to63: 11250, specialMultiple: 2 };
  var ROTH_CATCHUP_WAGES = 150000; // 414(v)(7): prior-year FICA wages above this -> age 50+ catch-ups must be Roth (2026)
  var FIRST_YEAR = 2002, MAX_ROWS = 70;
  // ------------------------------------------------------------------------------------------------

  function dollarLimit(year) { return LIMIT_BY_YEAR[year] || LIMITS.basic; }
  function ageCatchUp(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }

  // One catch-up year. basic = dollar limit, pool = unused limit carried in, gov = governmental plan.
  function catchUpYear(basic, catchUp, pool, pay, gov) {
    var ceiling = Math.min(basic, pay);
    var special = Math.min(LIMITS.specialMultiple * basic, ceiling + pool);
    var ageRoute = ceiling + (gov ? catchUp : 0);
    var useSpecial = special > ageRoute;
    var max = Math.min(pay, useSpecial ? special : ageRoute);
    var used = useSpecial ? Math.max(0, max - ceiling) : 0;
    return { ceiling: ceiling, special: special, ageRoute: Math.min(pay, ageRoute), max: max, useSpecial: useSpecial,
             tie: Math.abs(special - ageRoute) < 0.005 && special > ceiling, used: used, poolAfter: Math.max(0, pool - used) };
  }

  // p: birthYear, nra, hireYear, gov, pay, other, rows: [{ year, limit, deferred }]
  function compute(p) {
    var nraYear = p.birthYear + p.nra, start = nraYear - 3, end = nraYear - 1;
    var pool = p.other;
    p.rows.forEach(function (r) { pool += r.limit - r.deferred; });
    pool = Math.max(0, pool);
    var first = Math.max(start, LIMITS.year), out = [], total = 0, extra = 0, carried = pool;
    for (var y = first; y <= end; y++) {
      var age = y - p.birthYear, basic = dollarLimit(y);
      var c = catchUpYear(basic, ageCatchUp(age), pool, p.pay, p.gov);
      out.push({ year: y, age: age, basic: basic, ageRoute: c.ageRoute, special: Math.min(c.special, p.pay), max: c.max,
                 useSpecial: c.useSpecial, tie: c.tie, catchUp: p.gov ? ageCatchUp(age) : 0, poolAfter: c.poolAfter });
      total += c.max; extra += c.max - c.ageRoute;
      pool = c.poolAfter;
    }
    return { nraYear: nraYear, start: start, end: end, pool: carried, years: out, total: total, extra: extra };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }
  function isInt(v) { return !isNaN(v) && v === Math.round(v); }

  var saved = {}, rowKey = '';

  function td(text) { var c = document.createElement('td'); c.textContent = text; return c; }
  function cellInput(id, label, placeholder, value) {
    var cell = document.createElement('td');
    var group = document.createElement('div');
    group.className = 'input-group min-w-[8rem]';
    var affix = document.createElement('span');
    affix.className = 'input-affix'; affix.textContent = '$';
    var input = document.createElement('input');
    input.type = 'number'; input.id = id; input.className = 'form-input'; input.min = '0'; input.step = '500';
    input.setAttribute('inputmode', 'decimal'); input.setAttribute('aria-label', label);
    input.placeholder = placeholder; input.value = value || '';
    group.appendChild(affix); group.appendChild(input); cell.appendChild(group);
    return cell;
  }

  // Rebuild the worksheet rows when the range of years changes, keeping anything already typed.
  function buildRows(firstYear, lastYear, birthYear, typical) {
    var key = firstYear + '-' + lastYear + '-' + birthYear;
    var body = document.getElementById('scRows');
    if (key === rowKey) {
      for (var y0 = firstYear; y0 <= lastYear; y0++) document.getElementById('scDef' + y0).placeholder = String(typical);
      return;
    }
    for (var k in saved) if (saved.hasOwnProperty(k)) {
      var li = document.getElementById('scLim' + k), di = document.getElementById('scDef' + k);
      if (li && di) saved[k] = { lim: li.value, def: di.value };
    }
    rowKey = key;
    body.textContent = '';
    for (var y = firstYear; y <= lastYear; y++) {
      var keep = saved[y] || { lim: '', def: '' };
      saved[y] = keep;
      var tr = document.createElement('tr');
      tr.appendChild(td(String(y) + (y >= LIMITS.year ? ' (planned)' : '')));
      tr.appendChild(td(String(y - birthYear)));
      tr.appendChild(cellInput('scLim' + y, 'Limit for ' + y, String(dollarLimit(y)), keep.lim));
      tr.appendChild(cellInput('scDef' + y, 'Deferred in ' + y, String(typical), keep.def));
      var u = td('–'); u.id = 'scUnused' + y; tr.appendChild(u);
      body.appendChild(tr);
    }
  }

  function readRows(firstYear, lastYear, typical) {
    var rows = [], bad = false;
    for (var y = firstYear; y <= lastYear; y++) {
      var lr = document.getElementById('scLim' + y).value, dr = document.getElementById('scDef' + y).value;
      var lim = lr === '' ? dollarLimit(y) : parseFloat(lr), def = dr === '' ? typical : parseFloat(dr);
      saved[y] = { lim: lr, def: dr };
      if (isNaN(lim) || isNaN(def) || lim < 0 || def < 0) bad = true;
      rows.push({ year: y, limit: lim, deferred: def });
    }
    return { rows: rows, bad: bad };
  }

  function update() {
    var birthYear = num('scBirthYear'), nra = num('scNra'), hireYear = num('scHireYear'), typical = num('scTypical'),
        pay = num('scPay'), other = num('scOther'), gov = document.getElementById('scType').value === 'gov';
    var error = document.getElementById('scError');
    var bad = !isInt(birthYear) || !isInt(nra) || !isInt(hireYear) || [typical, pay, other].some(isNaN) ||
              birthYear < 1940 || birthYear > 2008 || nra < 40 || nra > 70 || hireYear < FIRST_YEAR || hireYear > 2060 ||
              hireYear <= birthYear + 14 || typical < 0 || pay <= 0 || other < 0;
    var nraYear = birthYear + nra, start = nraYear - 3, end = nraYear - 1;
    var lastPrior = Math.max(start, LIMITS.year) - 1;
    if (!bad && lastPrior - hireYear + 1 > MAX_ROWS) bad = true;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a birth year from 1940 to 2008, a normal retirement age from 40 to 70, a first plan year from ' +
                          FIRST_YEAR + ' (after age 14), pay above $0 and non-negative amounts.';
      return;
    }
    var passed = end < LIMITS.year;
    var passedEl = document.getElementById('scPassed');
    passedEl.hidden = !passed;
    var hasRows = !passed && lastPrior >= hireYear;
    if (hasRows) buildRows(hireYear, lastPrior, birthYear, typical);
    else { document.getElementById('scRows').textContent = ''; rowKey = ''; }
    var rr = hasRows ? readRows(hireYear, lastPrior, typical) : { rows: [], bad: false };
    if (rr.bad) {
      error.hidden = false;
      error.textContent = 'Worksheet amounts must be $0 or more.';
      return;
    }
    set('scNraYear', String(nraYear));
    set('scWindowYears', start + ' to ' + end + ' (ages ' + (start - birthYear) + ' to ' + (end - birthYear) + ')');
    set('scBasic', fmt(LIMITS.basic));
    set('scDouble', fmt(LIMITS.specialMultiple * LIMITS.basic));
    var futureEl = document.getElementById('scFutureNote');
    futureEl.hidden = !(end > LIMITS.year);
    if (end > LIMITS.year) set('scFutureNote', 'Years after ' + LIMITS.year + ' use the ' + LIMITS.year + ' limits until the IRS publishes new ones.');
    var body = document.getElementById('scWindow');
    body.textContent = '';
    if (passed) {
      set('scPassed', 'Your special catch-up years (' + start + ' to ' + end + ') have already passed. The special catch-up ' +
          'can’t be used in or after the year you reach normal retirement age.');
      ['scFirstMax', 'scPool', 'scWindowTotal', 'scExtra'].forEach(function (id) { set(id, '–'); });
      set('scFirstNote', ''); set('scRowsTotal', '–');
      document.getElementById('scChoice').hidden = true;
      document.getElementById('scRothNote').hidden = true;
      return;
    }
    var r = compute({ birthYear: birthYear, nra: nra, hireYear: hireYear, gov: gov, pay: pay, other: other, rows: rr.rows });
    rr.rows.forEach(function (row) { set('scUnused' + row.year, fmt(row.limit - row.deferred)); });
    set('scRowsTotal', fmt(r.pool));
    var f = r.years[0];
    set('scFirstMax', fmt(f.max));
    set('scFirstNote', 'In ' + f.year + ', age ' + f.age);
    set('scPool', fmt(r.pool));
    set('scWindowTotal', fmt(r.total));
    set('scExtra', fmt(r.extra));
    var choice = document.getElementById('scChoice');
    var someAge = r.years.some(function (y) { return !y.useSpecial && y.catchUp > 0; });
    choice.hidden = !gov;
    if (gov) {
      set('scChoice', someAge ? 'In some years the age 50+ catch-up gives you more than the special catch-up, so it applies ' +
          'instead and your unused limit carries forward. You can’t use both in the same year.' :
          'You can’t use the age 50+ catch-up and the special catch-up in the same year. The table uses whichever is larger.');
    }
    var roth = document.getElementById('scRothNote');
    roth.hidden = !(gov && pay > ROTH_CATCHUP_WAGES);
    if (gov && pay > ROTH_CATCHUP_WAGES) {
      set('scRothNote', 'If your prior-year Social Security wages from this employer were over ' + fmt(ROTH_CATCHUP_WAGES) +
          ', age 50+ catch-ups must go in as Roth. Special 457(b) catch-up contributions can still be pre-tax.');
    }
    r.years.forEach(function (y) {
      var tr = document.createElement('tr');
      var which = y.tie ? 'Either' : y.useSpecial ? 'Special 457(b)' : y.catchUp === LIMITS.catchUp60to63 ? 'Age 60–63' :
                  y.catchUp > 0 ? 'Age 50+' : 'Basic';
      [y.year, y.age, fmt(y.basic), gov && y.catchUp > 0 ? fmt(y.ageRoute) : '–', fmt(y.special), fmt(y.max), which,
       fmt(y.poolAfter)].forEach(function (v) { tr.appendChild(td(String(v))); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    ['scForm', 'scWorkForm'].forEach(function (id) {
      var form = document.getElementById(id);
      form.addEventListener('input', update);
      form.addEventListener('change', update);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
    });
    update();
  });
})();
